import os, glob, re

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
print("Loaded grids:", sorted(G.keys()))
for k, v in G.items():
    print(f"{k}: {len(v)}x{len(v[0])}")

import os, re, json

d = os.environ['RLM_SESSION_DIR']
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')

G = {}

def parse_grid(lines, h):
    return [[int(x) for x in line.split()] for line in lines]

for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n(.+)\Z', t, re.DOTALL):
    desc_full, rows_text = m.group(1), m.group(4)
    h, w = int(m.group(2)), int(m.group(3))
    row_lines = rows_text.strip().split('\n')[:h]

    if len(row_lines) != h:
        continue

    if all(len(line.split()) == w and all(c.isdigit() for c in line.split()) for line in row_lines):
        G[desc_full] = parse_grid(row_lines, h)

print("Loaded grids:", list(G.keys()))
for k in G:
    grid = G[k]
    print(f"  {k}: {len(grid)}x{len(grid[0]) if grid else 0}")

import os, json

d = os.environ['RLM_SESSION_DIR']
path = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'

with open(path) as f:
    lines = [json.loads(line) for line in f if line.strip()]

# Find message type with content containing grids
for i, msg in enumerate(lines):
    if msg.get('type') == 'message':
        print(f"\n=== Message {i} (role={msg.get('role')}):")
        # Try different content formats
        content = msg.get('content', '')
        if isinstance(content, str):
            print(f"  content[:400]: {content[:400]}")
        elif isinstance(content, dict):
            print(f"  keys: {list(content.keys())}")
            # Check common keys
            for key in ['content', 'parts', 'text', 'grid']:
                val = content.get(key)
                if val is not None:
                    print(f"  {key}: {str(val)[:200]}")
